WITH with_windows AS (SELECT *, NTILE(3) OVER (PARTITION BY segment ORDER BY credit_limit DESC, id) AS credit_limit_bucket, FIRST_VALUE(city) IGNORE NULLS OVER (PARTITION BY city ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_city, MIN(age) OVER (PARTITION BY country, city) AS country_min_age FROM customers), cleaned AS (SELECT *, UPPER(country) AS country_upper, COALESCE(city, 'N/A') AS resolved_city FROM with_windows WHERE signup_date > DATE '2023-10-13' AND city IS NOT NULL), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY credit_limit DESC NULLS LAST, id) AS rn FROM cleaned QUALIFY rn = 1), latest_match AS (SELECT s.*, top1.started_at FROM latest s JOIN LATERAL (SELECT c.started_at FROM sessions c WHERE c.customer_id = s.id ORDER BY c.started_at DESC, c.id DESC LIMIT 1) top1 ON TRUE), pivoted AS (SELECT * FROM (SELECT segment, country, city, country_min_age FROM latest_match) src PIVOT (AVG(country_min_age) FOR city IN ('Singapore' AS singapore, 'Tokyo' AS tokyo, 'London' AS london))) SELECT segment, country, singapore, tokyo, london FROM pivoted ORDER BY tokyo DESC;
